-- PostgreSQL baseline, part 1: tables, views, indexes, seed rows and helper functions.
--
-- Reproduces the FINAL state of SQLite migrations 001-006 (src/backend/database/migrations).
-- It does not replay the SQLite rebuild steps (ADR 0004, D2). Triggers are in 002.
-- schema_migrations is created by the runner (migrate.js), not here.
--
-- Deliberate dialect differences (ADR 0004, D3-D5):
--   * TEXT -> text, INTEGER -> bigint. The two rowid keys (workflow_events.id, audit_events.id)
--     are bigint GENERATED BY DEFAULT AS IDENTITY. 0/1 flags stay bigint with their CHECK.
--   * json_valid(x) -> x IS JSON. Timestamps stay ISO-8601 UTC text with their CHECKs.
--   * GLOB -> POSIX regex ('*' and '[...]' translated one by one); substr/length/BETWEEN keep
--     their meaning. Ordering comparisons rely on the C collation (ADR 0004, D4).
--   * julianday() -> julianday(text), a port of SQLite's date parser (see below). Its one deliberate
--     difference: 'now' returns NULL.
--     strftime('%Y-%m-%dT%H:%M:%fZ','now') -> coversaath_utc_now(); SQLite rounds the clock to a
--     millisecond, to_char truncates it.
--   * Columns added by SQLite ALTER TABLE ... ADD COLUMN are listed last, in the SQLite order.
--   * STRICT / WITHOUT ROWID have no PostgreSQL meaning and are dropped. Primary key columns are
--     NOT NULL in both engines (SQLite STRICT tables enforce it too).

-- Port of SQLite julianday(text). Accepts the inputs SQLite accepts: 'YYYY-MM-DD' with an optional
-- time ('HH:MM[:SS[.fff]]' after a space or 'T') and an optional 'Z' or +/-HH:MM zone (no zone means
-- UTC), a bare time, and a bare decimal julian day number. NULL, empty, garbage or any out-of-range
-- field returns NULL and never raises, as in SQLite, so a CHECK comparison passes and a guard
-- predicate fails closed in both engines. Calendar overflow (2026-02-30) rolls over as in SQLite.
-- The arithmetic mirrors SQLite's computeJD (integer milliseconds, then / 86400000.0).
-- Deliberate difference: the text 'now' returns NULL here (SQLite returns the current time), which
-- keeps the function IMMUTABLE. Use julianday(coversaath_utc_now()) for the current time.
CREATE FUNCTION julianday(input text) RETURNS double precision
LANGUAGE plpgsql IMMUTABLE STRICT PARALLEL SAFE AS $$
DECLARE
  parts text[];
  neg boolean := false;
  y bigint := 2000;
  mo bigint := 1;
  d bigint := 1;
  h bigint := 0;
  mi bigint := 0;
  secs double precision := 0;
  frac double precision := 0;
  scale double precision := 1;
  tz bigint := 0;
  has_time boolean := false;
  ijd bigint;
  a bigint;
  b bigint;
  x1 bigint;
  x2 bigint;
  r double precision;
  digits text;
  i integer;
BEGIN
  -- Date, optionally followed by a time. Groups: 1 sign, 2 Y, 3 M, 4 D, 5 h, 6 m, 7 s, 8 fraction,
  -- 9 'Z', 10 zone sign, 11 zone hours, 12 zone minutes.
  parts := regexp_match(input,
    '^(-?)([0-9]{4})-([0-9]{2})-([0-9]{2})[ \t\n\v\f\rT]*(?:([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\.([0-9]+))?)?[ \t\n\v\f\r]*(?:([Zz])|([+-])([0-9]{2}):([0-9]{2}))?[ \t\n\v\f\r]*)?$');
  IF parts IS NOT NULL THEN
    neg := parts[1] = '-';
    y := parts[2]::bigint;
    mo := parts[3]::bigint;
    d := parts[4]::bigint;
    IF y > 14712 OR mo < 1 OR mo > 12 OR d < 1 OR d > 31 THEN RETURN NULL; END IF;
    IF neg THEN y := -y; END IF;
  ELSE
    -- A bare time uses 2000-01-01 as its date. Groups: 1 h, 2 m, 3 s, 4 fraction, 5 'Z',
    -- 6 zone sign, 7 zone hours, 8 zone minutes.
    parts := regexp_match(input,
      '^([0-9]{2}):([0-9]{2})(?::([0-9]{2})(?:\.([0-9]+))?)?[ \t\n\v\f\r]*(?:([Zz])|([+-])([0-9]{2}):([0-9]{2}))?[ \t\n\v\f\r]*$');
    IF parts IS NOT NULL THEN
      parts := ARRAY[NULL, NULL, NULL, NULL] || parts;
    ELSIF input ~ '^[ \t\n\v\f\r]*[+-]?([0-9]+\.?[0-9]*|\.[0-9]+)([eE][+-]?[0-9]+)?[ \t\n\v\f\r]*$' THEN
      r := btrim(input, E' \t\n\v\f\r')::double precision;
      IF r >= 0.0 AND r < 5373484.5 THEN
        ijd := trunc(r * 86400000.0 + 0.5)::bigint;
        RETURN ijd::double precision / 86400000.0;
      END IF;
      RETURN NULL;
    ELSE
      RETURN NULL;
    END IF;
  END IF;

  -- parts[5..12] now hold the time and zone groups in both branches.
  IF parts[5] IS NOT NULL THEN
    has_time := true;
    h := parts[5]::bigint;
    mi := parts[6]::bigint;
    IF h > 24 OR mi > 59 THEN RETURN NULL; END IF;
    IF parts[7] IS NOT NULL THEN
      secs := parts[7]::bigint;
      IF secs > 59 THEN RETURN NULL; END IF;
    END IF;
    IF parts[8] IS NOT NULL THEN
      digits := parts[8];
      FOR i IN 1..length(digits) LOOP
        frac := frac * 10.0 + substr(digits, i, 1)::integer;
        scale := scale * 10.0;
      END LOOP;
      frac := frac / scale;
      IF frac > 0.999 THEN frac := 0.999; END IF;
      secs := secs + frac;
    END IF;
    IF parts[10] IS NOT NULL THEN
      IF parts[11]::bigint > 14 OR parts[12]::bigint > 59 THEN RETURN NULL; END IF;
      tz := (CASE parts[10] WHEN '-' THEN -1 ELSE 1 END) * (parts[12]::bigint + parts[11]::bigint * 60);
    END IF;
  END IF;

  a := y;
  IF mo <= 2 THEN
    a := y - 1;
    x2 := mo + 12;
  ELSE
    x2 := mo;
  END IF;
  b := a / 100;
  b := 2 - b + (b / 4);
  x1 := 36525 * (a + 4716) / 100;
  x2 := 306001 * (x2 + 1) / 10000;
  ijd := trunc((x1 + x2 + d + b - 1524.5) * 86400000.0)::bigint;
  IF has_time THEN
    ijd := ijd + h * 3600000 + mi * 60000 + trunc(secs * 1000.0 + 0.5)::bigint;
    ijd := ijd - tz * 60000;
  END IF;
  IF ijd < 0 OR ijd > 464269060799999 THEN RETURN NULL; END IF;
  RETURN ijd::double precision / 86400000.0;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$$;

-- strftime('%Y-%m-%dT%H:%M:%fZ', 'now'): UTC, millisecond precision, fixed at statement start.
CREATE FUNCTION coversaath_utc_now() RETURNS text
LANGUAGE sql STABLE AS $$
  SELECT to_char(statement_timestamp() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')
$$;

CREATE TABLE households (
  id text PRIMARY KEY,
  display_name text NOT NULL,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'restricted', 'closed')),
  created_at text NOT NULL,
  updated_at text NOT NULL
);

CREATE TABLE adult_users (
  id text PRIMARY KEY,
  display_name text NOT NULL,
  contact_email text,
  contact_phone text,
  locale text,
  account_status text NOT NULL DEFAULT 'invited' CHECK (account_status IN ('invited', 'active', 'suspended', 'closed')),
  created_at text NOT NULL,
  updated_at text NOT NULL
);

CREATE TABLE household_roles (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  adult_user_id text NOT NULL REFERENCES adult_users(id),
  role text NOT NULL CHECK (role IN ('owner', 'member', 'operator', 'backup_operator', 'viewer')),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'revoked')),
  starts_at text,
  ends_at text,
  created_at text NOT NULL,
  UNIQUE (household_id, adult_user_id, role)
);

CREATE TABLE household_members (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  adult_user_id text REFERENCES adult_users(id),
  display_name text NOT NULL,
  member_kind text NOT NULL CHECK (member_kind IN ('adult', 'dependent')),
  relationship_label text,
  date_of_birth text,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  CHECK ((member_kind = 'adult' AND adult_user_id IS NOT NULL) OR member_kind = 'dependent')
);

CREATE TABLE consent_grants (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  subject_adult_id text NOT NULL REFERENCES adult_users(id),
  granted_to_actor text NOT NULL,
  purpose text NOT NULL CHECK (purpose IN (
    'profile_intake', 'document_processing', 'coverage_reconstruction', 'voice_intake',
    'institutional_clarification', 'human_review', 'purchase_review', 'payment'
  )),
  notice_version text NOT NULL,
  evidence_method text NOT NULL CHECK (evidence_method IN ('typed', 'voice_recorded', 'signed', 'fixture')),
  granted_at text NOT NULL,
  expires_at text,
  revoked_at text,
  created_at text NOT NULL,
  CHECK (revoked_at IS NULL OR revoked_at >= granted_at)
);

CREATE TABLE consent_scopes (
  id text PRIMARY KEY,
  consent_grant_id text NOT NULL REFERENCES consent_grants(id),
  resource_type text NOT NULL CHECK (resource_type IN ('profile_field', 'document', 'policy', 'case', 'voice_call', 'payment_order')),
  resource_id text,
  action text NOT NULL CHECK (action IN ('collect', 'read', 'derive', 'share', 'contact', 'approve', 'pay')),
  data_category text NOT NULL,
  recipient text,
  created_at text NOT NULL,
  UNIQUE (consent_grant_id, resource_type, resource_id, action, data_category, recipient)
);

CREATE TABLE consent_revocations (
  id text PRIMARY KEY,
  consent_grant_id text NOT NULL UNIQUE REFERENCES consent_grants(id),
  revoked_by_adult_id text NOT NULL REFERENCES adult_users(id),
  reason text,
  revoked_at text NOT NULL,
  downstream_deletion_due_at text,
  created_at text NOT NULL
);

CREATE TABLE service_cases (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  subject_member_id text REFERENCES household_members(id),
  opened_by_adult_id text NOT NULL REFERENCES adult_users(id),
  trigger_type text NOT NULL CHECK (trigger_type IN ('renewal', 'workforce_entry', 'family_change', 'planned_care', 'emergency', 'user_requested_review')),
  status text NOT NULL DEFAULT 'created' CHECK (status IN ('created', 'collecting', 'processing', 'human_review', 'blocked', 'ready', 'closed', 'revoked')),
  emergency_mode bigint NOT NULL DEFAULT 0 CHECK (emergency_mode IN (0, 1)),
  stated_estimate_minor bigint CHECK (stated_estimate_minor IS NULL OR stated_estimate_minor >= 0),
  currency text CHECK (currency IS NULL OR length(currency) = 3),
  created_at text NOT NULL,
  updated_at text NOT NULL,
  closed_at text
);

CREATE TABLE case_participants (
  case_id text NOT NULL REFERENCES service_cases(id),
  adult_user_id text NOT NULL REFERENCES adult_users(id),
  participant_role text NOT NULL CHECK (participant_role IN ('requester', 'subject', 'operator', 'backup_operator', 'reviewer')),
  consent_grant_id text REFERENCES consent_grants(id),
  created_at text NOT NULL,
  PRIMARY KEY (case_id, adult_user_id, participant_role)
);

CREATE TABLE document_uploads (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  case_id text REFERENCES service_cases(id),
  uploaded_by_adult_id text NOT NULL REFERENCES adult_users(id),
  consent_grant_id text NOT NULL REFERENCES consent_grants(id),
  document_kind text NOT NULL CHECK (document_kind IN ('policy_wording', 'policy_schedule', 'endorsement', 'member_card', 'hospital_estimate', 'medical_record', 'identity_record', 'other')),
  original_filename text NOT NULL,
  storage_path text NOT NULL UNIQUE,
  content_sha256 text NOT NULL CHECK (length(content_sha256) = 64),
  mime_type text NOT NULL,
  byte_size bigint NOT NULL CHECK (byte_size > 0),
  malware_status text NOT NULL DEFAULT 'pending' CHECK (malware_status IN ('pending', 'clean', 'blocked', 'not_scanned_fixture')),
  encryption_status text NOT NULL DEFAULT 'required' CHECK (encryption_status IN ('required', 'encrypted_local', 'fixture_only')),
  lifecycle_state text NOT NULL DEFAULT 'active' CHECK (lifecycle_state IN ('active', 'quarantined', 'deletion_requested', 'deleted')),
  uploaded_at text NOT NULL,
  deleted_at text,
  -- Added by SQLite 004.
  logical_document_id text,
  source_version text NOT NULL DEFAULT '1'
);

CREATE TABLE ocr_jobs (
  id text PRIMARY KEY,
  document_upload_id text NOT NULL REFERENCES document_uploads(id),
  provider text NOT NULL CHECK (provider IN ('sarvam', 'fixture')),
  provider_job_ref text,
  status text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'submitted', 'processing', 'succeeded', 'failed', 'cancelled')),
  attempt_count bigint NOT NULL DEFAULT 0 CHECK (attempt_count >= 0 AND attempt_count <= 5),
  error_code text,
  error_message text,
  requested_at text NOT NULL,
  started_at text,
  completed_at text,
  -- Added by SQLite 004.
  contract_version text NOT NULL DEFAULT 'knowvia.ocr.v1',
  authorization_json text CHECK (authorization_json IS NULL OR authorization_json IS JSON),
  result_json text CHECK (result_json IS NULL OR result_json IS JSON),
  result_digest text CHECK (result_digest IS NULL OR length(result_digest) = 64),
  updated_at text,
  UNIQUE (provider, provider_job_ref)
);

CREATE TABLE source_pages (
  id text PRIMARY KEY,
  document_upload_id text NOT NULL REFERENCES document_uploads(id),
  ocr_job_id text REFERENCES ocr_jobs(id),
  page_number bigint NOT NULL CHECK (page_number > 0),
  source_version text NOT NULL,
  page_sha256 text NOT NULL CHECK (length(page_sha256) = 64),
  extracted_text text,
  extraction_status text NOT NULL CHECK (extraction_status IN ('pending', 'extracted', 'failed', 'manual_verified')),
  confidence_basis_points bigint CHECK (confidence_basis_points IS NULL OR confidence_basis_points BETWEEN 0 AND 10000),
  created_at text NOT NULL,
  -- Added by SQLite 004.
  output_contract_version text NOT NULL DEFAULT 'knowvia.ocr.v1',
  text_sha256 text CHECK (text_sha256 IS NULL OR length(text_sha256) = 64),
  provider_page_ref text,
  provenance_json text CHECK (provenance_json IS NULL OR provenance_json IS JSON),
  UNIQUE (document_upload_id, source_version, page_number)
);

CREATE TABLE insurers (
  id text PRIMARY KEY,
  legal_name text NOT NULL,
  regulator_identifier text,
  created_at text NOT NULL
);

CREATE TABLE policies (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  insurer_id text REFERENCES insurers(id),
  policy_kind text NOT NULL CHECK (policy_kind IN ('group', 'personal', 'top_up', 'unknown')),
  policy_number_masked text,
  policy_version text,
  starts_on text,
  ends_on text,
  source_document_id text REFERENCES document_uploads(id),
  verification_state text NOT NULL DEFAULT 'unverified' CHECK (verification_state IN ('unverified', 'document_backed', 'institution_confirmed', 'conflicted')),
  created_at text NOT NULL,
  updated_at text NOT NULL
);

CREATE TABLE policy_members (
  policy_id text NOT NULL REFERENCES policies(id),
  household_member_id text NOT NULL REFERENCES household_members(id),
  membership_state text NOT NULL CHECK (membership_state IN ('unknown', 'stated', 'document_backed', 'institution_confirmed', 'conflicted')),
  member_reference_masked text,
  source_page_id text REFERENCES source_pages(id),
  created_at text NOT NULL,
  PRIMARY KEY (policy_id, household_member_id)
);

-- Final shape from SQLite 002 (the evidence ledger rebuild).
CREATE TABLE evidence_facts (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  case_id text REFERENCES service_cases(id),
  policy_id text REFERENCES policies(id),
  subject_member_id text REFERENCES household_members(id),
  fact_key text NOT NULL,
  value_json text CHECK (value_json IS NULL OR value_json IS JSON),
  epistemic_state text NOT NULL CHECK (epistemic_state IN ('known', 'unknown', 'conflict')),
  evidence_kind text NOT NULL CHECK (evidence_kind IN ('document', 'adult_statement', 'institutional_reply', 'calculation', 'fixture')),
  provenance_kind text NOT NULL CHECK (provenance_kind IN ('document_page', 'adult_statement', 'proxy_statement', 'institutional_reply', 'calculation', 'fixture')),
  source_page_id text REFERENCES source_pages(id),
  statement_adult_id text REFERENCES adult_users(id),
  institutional_source_ref text,
  calculation_method text,
  source_locator text,
  asserted_by text NOT NULL,
  effective_at text,
  observed_at text NOT NULL,
  retrieved_at text,
  confidence_basis_points bigint CHECK (confidence_basis_points IS NULL OR confidence_basis_points BETWEEN 0 AND 10000),
  review_status text NOT NULL DEFAULT 'unreviewed' CHECK (review_status IN ('unreviewed', 'reviewed', 'rejected')),
  subject_confirmation_state text NOT NULL DEFAULT 'not_applicable' CHECK (subject_confirmation_state IN ('not_applicable', 'unconfirmed', 'confirmed', 'rejected')),
  permitted_viewers_json text CHECK (permitted_viewers_json IS NULL OR permitted_viewers_json IS JSON),
  expires_at text,
  supersedes_fact_id text REFERENCES evidence_facts(id),
  created_at text NOT NULL,
  CHECK (
    (epistemic_state = 'unknown' AND value_json IS NULL) OR
    (epistemic_state IN ('known', 'conflict') AND value_json IS NOT NULL)
  ),
  CHECK (epistemic_state = 'unknown' OR provenance_kind <> 'document_page' OR source_page_id IS NOT NULL),
  CHECK (epistemic_state = 'unknown' OR provenance_kind NOT IN ('adult_statement', 'proxy_statement') OR statement_adult_id IS NOT NULL),
  CHECK (epistemic_state = 'unknown' OR provenance_kind <> 'institutional_reply' OR institutional_source_ref IS NOT NULL),
  CHECK (epistemic_state = 'unknown' OR provenance_kind <> 'calculation' OR calculation_method IS NOT NULL),
  CHECK (provenance_kind <> 'proxy_statement' OR subject_confirmation_state <> 'not_applicable')
);

CREATE TABLE fact_conflicts (
  id text PRIMARY KEY,
  fact_key text NOT NULL,
  left_fact_id text NOT NULL REFERENCES evidence_facts(id),
  right_fact_id text NOT NULL REFERENCES evidence_facts(id),
  resolution_state text NOT NULL DEFAULT 'open' CHECK (resolution_state IN ('open', 'resolved', 'accepted_unknown')),
  resolved_by_review_id text,
  created_at text NOT NULL,
  resolved_at text,
  CHECK (left_fact_id <> right_fact_id)
);

CREATE TABLE coverage_graph_snapshots (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  case_id text NOT NULL REFERENCES service_cases(id),
  version bigint NOT NULL CHECK (version > 0),
  status text NOT NULL CHECK (status IN ('draft', 'reviewed', 'released', 'superseded')),
  graph_json text NOT NULL CHECK (graph_json IS JSON),
  generated_by_run_id text,
  created_at text NOT NULL,
  UNIQUE (case_id, version)
);

CREATE TABLE coverage_graph_nodes (
  id text PRIMARY KEY,
  snapshot_id text NOT NULL REFERENCES coverage_graph_snapshots(id),
  node_type text NOT NULL CHECK (node_type IN ('household_member', 'policy', 'protection', 'constraint', 'institution', 'unknown')),
  entity_ref text,
  label text NOT NULL,
  epistemic_state text NOT NULL CHECK (epistemic_state IN ('known', 'unknown', 'conflict')),
  source_fact_id text REFERENCES evidence_facts(id),
  created_at text NOT NULL,
  UNIQUE (snapshot_id, id)
);

CREATE TABLE coverage_graph_edges (
  id text PRIMARY KEY,
  snapshot_id text NOT NULL REFERENCES coverage_graph_snapshots(id),
  from_node_id text NOT NULL REFERENCES coverage_graph_nodes(id),
  to_node_id text NOT NULL REFERENCES coverage_graph_nodes(id),
  relationship text NOT NULL,
  source_fact_id text REFERENCES evidence_facts(id),
  created_at text NOT NULL,
  CHECK (from_node_id <> to_node_id)
);

CREATE TABLE workflow_runs (
  id text PRIMARY KEY,
  case_id text NOT NULL REFERENCES service_cases(id),
  workflow_name text NOT NULL,
  workflow_version text NOT NULL,
  execution_mode text NOT NULL CHECK (execution_mode IN ('fixture', 'live')),
  status text NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'blocked', 'failed', 'cancelled', 'revoked', 'interrupted')),
  input_digest text NOT NULL,
  started_at text,
  finished_at text,
  created_at text NOT NULL,
  -- Added by SQLite 002.
  case_revision text,
  consent_grant_id text REFERENCES consent_grants(id),
  input_json text CHECK (input_json IS NULL OR input_json IS JSON),
  terminal_reason text
);

CREATE TABLE workflow_tasks (
  id text PRIMARY KEY,
  workflow_run_id text NOT NULL REFERENCES workflow_runs(id),
  parent_task_id text REFERENCES workflow_tasks(id),
  agent_name text NOT NULL,
  task_kind text NOT NULL,
  status text NOT NULL CHECK (status IN ('pending', 'running', 'completed', 'blocked', 'failed', 'cancelled', 'revoked', 'interrupted')),
  attempt_count bigint NOT NULL DEFAULT 0 CHECK (attempt_count BETWEEN 0 AND 5),
  input_digest text,
  output_digest text,
  started_at text,
  finished_at text,
  created_at text NOT NULL,
  -- Added by SQLite 002.
  input_json text CHECK (input_json IS NULL OR input_json IS JSON),
  output_json text CHECK (output_json IS NULL OR output_json IS JSON),
  lease_owner text,
  lease_expires_at text,
  retry_available_at text,
  last_error_code text,
  last_error_message text,
  terminal_reason text
);

CREATE TABLE workflow_task_dependencies (
  workflow_task_id text NOT NULL REFERENCES workflow_tasks(id),
  depends_on_task_id text NOT NULL REFERENCES workflow_tasks(id),
  created_at text NOT NULL,
  PRIMARY KEY (workflow_task_id, depends_on_task_id),
  CHECK (workflow_task_id <> depends_on_task_id)
);

CREATE TABLE workflow_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  workflow_run_id text NOT NULL REFERENCES workflow_runs(id),
  workflow_task_id text REFERENCES workflow_tasks(id),
  event_type text NOT NULL,
  event_payload_json text NOT NULL CHECK (event_payload_json IS JSON),
  occurred_at text NOT NULL
);

CREATE TABLE reviewer_findings (
  id text PRIMARY KEY,
  workflow_run_id text NOT NULL REFERENCES workflow_runs(id),
  workflow_task_id text REFERENCES workflow_tasks(id),
  reviewer_kind text NOT NULL CHECK (reviewer_kind IN ('evidence', 'privacy', 'safety', 'regulated_boundary', 'human')),
  severity text NOT NULL CHECK (severity IN ('info', 'warning', 'blocker')),
  finding_code text NOT NULL,
  message text NOT NULL,
  source_fact_id text REFERENCES evidence_facts(id),
  resolved_at text,
  resolution_note text,
  created_at text NOT NULL
);

CREATE TABLE release_gates (
  id text PRIMARY KEY,
  workflow_run_id text NOT NULL REFERENCES workflow_runs(id),
  gate_kind text NOT NULL CHECK (gate_kind IN ('evidence', 'privacy', 'safety', 'regulated_recommendation', 'external_action')),
  status text NOT NULL CHECK (status IN ('pending', 'passed', 'blocked', 'human_review_required')),
  blocker_count bigint NOT NULL DEFAULT 0 CHECK (blocker_count >= 0),
  decided_by text NOT NULL,
  decided_at text,
  created_at text NOT NULL,
  UNIQUE (workflow_run_id, gate_kind),
  CHECK (status <> 'passed' OR blocker_count = 0)
);

CREATE TABLE human_reviews (
  id text PRIMARY KEY,
  case_id text NOT NULL REFERENCES service_cases(id),
  workflow_run_id text REFERENCES workflow_runs(id),
  reviewer_adult_id text REFERENCES adult_users(id),
  review_kind text NOT NULL CHECK (review_kind IN ('licensed_recommendation', 'ambiguity', 'exception', 'customer_requested', 'emergency_handoff')),
  status text NOT NULL CHECK (status IN ('requested', 'in_progress', 'completed', 'declined')),
  recommendation_outcome text CHECK (recommendation_outcome IS NULL OR recommendation_outcome IN ('buy', 'retain', 'defer', 'no_recommendation')),
  conflict_disclosure_shown bigint NOT NULL DEFAULT 0 CHECK (conflict_disclosure_shown IN (0, 1)),
  started_at text,
  completed_at text,
  created_at text NOT NULL
);

CREATE TABLE human_approvals (
  id text PRIMARY KEY,
  case_id text NOT NULL REFERENCES service_cases(id),
  adult_user_id text NOT NULL REFERENCES adult_users(id),
  consent_grant_id text NOT NULL REFERENCES consent_grants(id),
  approval_kind text NOT NULL CHECK (approval_kind IN ('share_data', 'voice_call', 'declaration', 'purchase', 'payment', 'record_reply')),
  target_type text NOT NULL,
  target_id text NOT NULL,
  decision text NOT NULL CHECK (decision IN ('approved', 'rejected', 'withdrawn')),
  approved_payload_digest text NOT NULL,
  decided_at text NOT NULL,
  created_at text NOT NULL,
  UNIQUE (adult_user_id, approval_kind, target_type, target_id, approved_payload_digest)
);

CREATE TABLE integration_outbox (
  id text PRIMARY KEY,
  case_id text REFERENCES service_cases(id),
  provider text NOT NULL CHECK (provider IN ('sarvam', 'gnani', 'pine_labs', 'email')),
  operation text NOT NULL,
  payload_json text NOT NULL CHECK (payload_json IS JSON),
  payload_digest text NOT NULL,
  consent_grant_id text NOT NULL REFERENCES consent_grants(id),
  human_approval_id text REFERENCES human_approvals(id),
  release_gate_id text REFERENCES release_gates(id),
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'processing', 'sent', 'failed', 'cancelled', 'blocked')),
  attempt_count bigint NOT NULL DEFAULT 0 CHECK (attempt_count BETWEEN 0 AND 5),
  available_at text NOT NULL,
  locked_at text,
  last_error text,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  CHECK (provider = 'sarvam' OR human_approval_id IS NOT NULL),
  CHECK (provider NOT IN ('pine_labs', 'email') OR release_gate_id IS NOT NULL)
);

CREATE TABLE integration_webhook_events (
  id text PRIMARY KEY,
  provider text NOT NULL CHECK (provider IN ('sarvam', 'gnani', 'pine_labs', 'email')),
  provider_event_id text NOT NULL,
  event_type text NOT NULL,
  signature_status text NOT NULL CHECK (signature_status IN ('pending', 'verified', 'invalid', 'fixture')),
  payload_json text NOT NULL CHECK (payload_json IS JSON),
  received_at text NOT NULL,
  processed_at text,
  processing_error text,
  UNIQUE (provider, provider_event_id)
);

CREATE TABLE idempotency_keys (
  scope text NOT NULL,
  idempotency_key text NOT NULL,
  request_digest text NOT NULL,
  response_status bigint,
  response_json text CHECK (response_json IS NULL OR response_json IS JSON),
  locked_until text,
  expires_at text NOT NULL,
  created_at text NOT NULL,
  PRIMARY KEY (scope, idempotency_key)
);

CREATE TABLE retention_records (
  id text PRIMARY KEY,
  household_id text NOT NULL REFERENCES households(id),
  resource_type text NOT NULL CHECK (resource_type IN ('household', 'adult_user', 'case', 'document', 'source_page', 'workflow_run', 'integration_payload')),
  resource_id text NOT NULL,
  retention_basis text NOT NULL,
  retain_until text,
  deletion_state text NOT NULL DEFAULT 'active' CHECK (deletion_state IN ('active', 'requested', 'blocked_legal_hold', 'scheduled', 'deleted', 'verified')),
  requested_by_adult_id text REFERENCES adult_users(id),
  requested_at text,
  deleted_at text,
  verified_at text,
  created_at text NOT NULL,
  updated_at text NOT NULL,
  UNIQUE (resource_type, resource_id)
);

CREATE TABLE audit_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  household_id text REFERENCES households(id),
  case_id text REFERENCES service_cases(id),
  actor_type text NOT NULL CHECK (actor_type IN ('adult_user', 'system', 'agent', 'human_reviewer', 'integration')),
  actor_id text NOT NULL,
  action text NOT NULL,
  resource_type text NOT NULL,
  resource_id text NOT NULL,
  event_payload_json text NOT NULL CHECK (event_payload_json IS JSON),
  previous_event_hash text,
  event_hash text NOT NULL UNIQUE CHECK (length(event_hash) = 64),
  occurred_at text NOT NULL
);

-- SQLite 003.
CREATE TABLE api_sessions (
  id text PRIMARY KEY,
  adult_user_id text NOT NULL REFERENCES adult_users(id),
  token_sha256 text NOT NULL UNIQUE CHECK (length(token_sha256) = 64),
  issued_at text NOT NULL,
  expires_at text NOT NULL,
  revoked_at text,
  last_seen_at text,
  created_at text NOT NULL,
  CHECK (julianday(expires_at) > julianday(issued_at)),
  CHECK (revoked_at IS NULL OR julianday(revoked_at) >= julianday(issued_at))
);

-- SQLite 005. GLOB patterns are translated to anchored POSIX regexes; 'NOT GLOB *[^set]*' becomes
-- 'NOT (x ~ [^set])' (no character outside the set).
CREATE TABLE coverage_parameter_registry_versions (
  version text PRIMARY KEY CHECK (
    length(version) BETWEEN 3 AND 64
    AND version ~ '^policy-parameters/v[0-9]'
    AND NOT (version ~ '[^a-z0-9/.-]')
  ),
  registered_at text NOT NULL
);

-- A new registry version is a new row here plus an entry in the application registry.
INSERT INTO coverage_parameter_registry_versions (version, registered_at)
VALUES ('policy-parameters/v1', coversaath_utc_now());

CREATE TABLE coverage_parameter_registry_pins (
  workflow_run_id text PRIMARY KEY REFERENCES workflow_runs(id),
  registry_version text NOT NULL REFERENCES coverage_parameter_registry_versions(version),
  pinned_at text NOT NULL,
  created_at text NOT NULL,
  UNIQUE (workflow_run_id, registry_version)
);

CREATE TABLE coverage_parameter_records (
  id text PRIMARY KEY,
  workflow_run_id text NOT NULL,
  registry_version text NOT NULL,
  parameter_key text NOT NULL CHECK (
    length(parameter_key) BETWEEN 3 AND 128
    AND substr(parameter_key, 1, 1) BETWEEN 'a' AND 'k'
    AND substr(parameter_key, 2, 1) = '.'
    AND NOT (substr(parameter_key, 3) ~ '[^a-z0-9_]')
  ),
  household_id text NOT NULL REFERENCES households(id),
  case_id text NOT NULL REFERENCES service_cases(id),
  subject_id text NOT NULL REFERENCES household_members(id),
  policy_id text NOT NULL REFERENCES policies(id),
  applicable bigint NOT NULL DEFAULT 1 CHECK (applicable IN (0, 1)),
  created_at text NOT NULL,
  updated_at text NOT NULL,
  UNIQUE (workflow_run_id, parameter_key),
  FOREIGN KEY (workflow_run_id, registry_version)
    REFERENCES coverage_parameter_registry_pins(workflow_run_id, registry_version)
);

CREATE TABLE coverage_parameter_acquisitions (
  parameter_record_id text PRIMARY KEY REFERENCES coverage_parameter_records(id),
  acquisition_state text NOT NULL CHECK (acquisition_state IN (
    'not_requested', 'requested', 'received', 'rejected', 'not_permitted'
  )),
  reason_code text CHECK (reason_code IS NULL OR length(reason_code) BETWEEN 1 AND 128),
  requested_at text,
  received_at text,
  updated_by text NOT NULL CHECK (length(updated_by) BETWEEN 1 AND 128),
  updated_at text NOT NULL,
  CHECK (acquisition_state <> 'requested' OR requested_at IS NOT NULL),
  CHECK (acquisition_state <> 'received' OR (received_at IS NOT NULL AND requested_at IS NOT NULL))
);

CREATE TABLE coverage_parameter_observations (
  id text PRIMARY KEY,
  parameter_record_id text NOT NULL REFERENCES coverage_parameter_records(id),
  source_id text NOT NULL REFERENCES source_pages(id),
  document_id text NOT NULL REFERENCES document_uploads(id),
  version text NOT NULL CHECK (length(version) BETWEEN 1 AND 128),
  page text NOT NULL CHECK (length(page) BETWEEN 1 AND 64),
  extraction_method text NOT NULL CHECK (extraction_method IN (
    'deterministic_calculation', 'document_extraction', 'human_report', 'human_review',
    'official_source_lookup'
  )),
  review_status text NOT NULL CHECK (review_status IN (
    'not_reviewed', 'accepted', 'rejected', 'superseded'
  )),
  value_json text CHECK (value_json IS NULL OR value_json IS JSON),
  source_digest text NOT NULL CHECK (
    length(source_digest) = 64 AND NOT (source_digest ~ '[^a-f0-9]')
  ),
  observed_at text NOT NULL,
  recorded_by text NOT NULL CHECK (length(recorded_by) BETWEEN 1 AND 128),
  created_at text NOT NULL,
  redacted_at text,
  redaction_reason_code text CHECK (
    redaction_reason_code IS NULL OR (
      length(redaction_reason_code) BETWEEN 1 AND 64
      AND NOT (redaction_reason_code ~ '[^a-z0-9_]')
    )
  ),
  CHECK (
    (redacted_at IS NULL AND redaction_reason_code IS NULL AND value_json IS NOT NULL)
    OR (redacted_at IS NOT NULL AND redaction_reason_code IS NOT NULL AND value_json IS NULL)
  )
);

CREATE TABLE coverage_parameter_resolutions (
  parameter_record_id text PRIMARY KEY REFERENCES coverage_parameter_records(id),
  resolution_state text NOT NULL CHECK (resolution_state IN (
    'unknown', 'reported', 'extracted_unverified', 'proven', 'calculated',
    'dynamic', 'conflicting', 'not_permitted'
  )),
  resolved_value_json text CHECK (resolved_value_json IS NULL OR resolved_value_json IS JSON),
  resolved_observation_id text REFERENCES coverage_parameter_observations(id),
  reason_code text CHECK (reason_code IS NULL OR length(reason_code) BETWEEN 1 AND 128),
  transition_authority text NOT NULL CHECK (transition_authority IN (
    'deterministic', 'human_reviewer', 'model', 'official_source'
  )),
  updated_by text NOT NULL CHECK (length(updated_by) BETWEEN 1 AND 128),
  updated_at text NOT NULL,
  CHECK (
    transition_authority <> 'model'
    OR resolution_state IN ('unknown', 'extracted_unverified', 'conflicting')
  ),
  CHECK (
    (resolution_state IN ('unknown', 'conflicting', 'not_permitted')
      AND resolved_value_json IS NULL AND resolved_observation_id IS NULL)
    OR
    (resolution_state IN ('reported', 'extracted_unverified', 'proven', 'calculated', 'dynamic')
      AND resolved_value_json IS NOT NULL AND resolved_observation_id IS NOT NULL)
  )
);

CREATE TABLE coverage_parameter_observation_rules (
  extraction_method text NOT NULL,
  resolution_state text NOT NULL,
  transition_authority text NOT NULL CHECK (transition_authority IN (
    'deterministic', 'human_reviewer', 'model', 'official_source'
  )),
  requires_accepted bigint NOT NULL CHECK (requires_accepted IN (0, 1)),
  PRIMARY KEY (extraction_method, resolution_state),
  CHECK (transition_authority <> 'model' OR resolution_state = 'extracted_unverified')
);

INSERT INTO coverage_parameter_observation_rules
  (extraction_method, resolution_state, transition_authority, requires_accepted)
VALUES
  ('document_extraction', 'extracted_unverified', 'model', 0),
  ('human_report', 'reported', 'deterministic', 0),
  ('human_review', 'reported', 'human_reviewer', 0),
  ('human_review', 'proven', 'human_reviewer', 1),
  ('official_source_lookup', 'proven', 'official_source', 1),
  ('official_source_lookup', 'dynamic', 'official_source', 0),
  ('deterministic_calculation', 'calculated', 'deterministic', 0),
  ('deterministic_calculation', 'dynamic', 'deterministic', 0);

-- Indexes: SQLite 001 (not dropped by the 002 rebuild), then 002, 003, 004 and 005.
